"""Review-only independent audit of persisted V23 data; no producer or PDE."""
import csv
import hashlib
import json
import pathlib
import subprocess
import time
import xml.etree.ElementTree as ET

import numpy as np

ROOT = pathlib.Path('/home/fenics/Projects/NN-Lab-V2')
OUT = ROOT / 'tmp/task42extra/review_v23'
REC = ROOT / 'docs/task042extra_feinn_5nm/outcomes/records'
start = time.monotonic()
def read(p):
    return json.loads(pathlib.Path(p).read_text())
def digest(p):
    with pathlib.Path(p).open('rb') as f:
        return hashlib.file_digest(f, 'sha256').hexdigest()
records = {p.name: read(p) for p in sorted(REC.glob('*_v23.json'))}
bindings = {}
def collect(obj):
    if isinstance(obj, dict):
        if isinstance(obj.get('path'), str) and isinstance(obj.get('sha256'), str):
            p = pathlib.Path(obj['path']); p = p if p.is_absolute() else ROOT / p
            bindings[(str(p), obj['sha256'])] = obj
        for v in obj.values(): collect(v)
    elif isinstance(obj, list):
        for v in obj: collect(v)
for d in records.values(): collect(d)
index = {k: read(v['path']) for k, v in records['run_index_v23.json']['indices'].items()}
for d in index.values(): collect(d)
checks = []
for (p, expected), entry in sorted(bindings.items()):
    exists = pathlib.Path(p).is_file()
    actual = digest(p) if exists else None
    row = dict(path=p, expected=expected, actual=actual, status='PASS' if actual == expected else 'UNRESOLVED')
    if exists and 'bytes' in entry: row['bytes_match'] = pathlib.Path(p).stat().st_size == entry['bytes']
    checks.append(row)

def arrays(p):
    with np.load(p, allow_pickle=False) as z:
        return {k: np.array(z[k]) for k in z.files}
qidx = index['v23_facet_qualification']
oracle = arrays(qidx['files']['oracle']['path'])
digits = read(qidx['files']['decimal_moments']['path'])
converted = np.array([[complex(float(r),float(i)) for r,i in row] for row in digits])
assert np.array_equal(converted, oracle['moment_oracle110'])
assert len(oracle['frequencies']) == 1213
assert np.isfinite(oracle['frequencies']).all()
mom_self = float(np.max(abs(oracle['moment_oracle80']-oracle['moment_oracle110'])))
csv_rows = list(csv.DictReader((REC/'local_case_errors_v23.csv').open()))
csv_index = {(r['implementation'],int(r['degree']),int(r['local_mode_index']),r['quantity'],int(r['direction'])):r for r in csv_rows}
assert len(csv_rows) == len(csv_index) == 864
def measure(a,b):
    numerator = float(np.sqrt(np.sum(np.abs(np.asarray(a)-b)**2)))
    norm = float(np.sqrt(np.sum(np.abs(b)**2)))
    return dict(numerator=numerator, reference_norm=norm, denominator=max(norm,1e-12), relative=numerator/max(norm,1e-12), near_zero=bool(norm<1e-12))
implementations = {}; compared=0; csv_abs={k:0. for k in ('numerator','reference_norm','denominator','relative')}
for name in ('analytic','q60'):
    idx = index['v23_'+name+'_cold']; a = arrays(idx['files']['cold_arrays']['path'])
    assert all(np.isfinite(x).all() for x in a.values())
    interval = np.abs(a['moment_values']-oracle['moment_oracle110'])
    wi = np.unravel_index(int(interval.argmax()),interval.shape)
    per_degree={}
    for p,dim in ((4,300),(6,882)):
        c=oracle[f'p{p}_directions']; g=oracle[f'p{p}_load']
        B,D,H=(oracle[f'p{p}_{x}'] for x in ('B','D','H'))
        assert B.shape == D.shape == (24,dim) and c.shape == (3,dim) and g.shape == H.shape == (24,)
        assert np.isfinite(B).all() and np.isfinite(D).all() and np.all(H>0)
        expected=dict(B=B,D=D,H=H,forward=B@c.T,projection=(D@c.T+g[:,None])/H[:,None],adjoint=B.conj().T@g)
        own_B,own_D,own_H=(a[f'p{p}_{x}'] for x in ('B','D','H'))
        own_expected=dict(forward=own_B@c.T,projection=(own_D@c.T+g[:,None])/own_H[:,None],adjoint=own_B.conj().T@g)
        own_identity={k:measure(a[f'p{p}_{k}'],v) for k,v in own_expected.items()}
        assert all(x['relative']<1e-13 for x in own_identity.values())
        whole={k:measure(a[f'p{p}_{k}'],v) for k,v in expected.items()}
        worst=dict(relative=-1.); nears=0
        for row,key in enumerate(qidx['result']['local'][str(p)]['case_keys']):
            for quantity in ('B','D','H','forward','projection'):
                av,bv=a[f'p{p}_{quantity}'][row],expected[quantity][row]
                pairs=[(-1,av,bv)] if quantity in ('B','D','H') else [(d,av[d],bv[d]) for d in range(3)]
                for direction,x,y in pairs:
                    m=measure(x,y); r=csv_index[(name,p,row,quantity,direction)]; compared+=1
                    assert json.loads(r['mode_key']) == key
                    assert (r['near_zero']=='True') == m['near_zero']; nears+=m['near_zero']
                    for col in csv_abs:
                        csv_abs[col]=max(csv_abs[col],abs(m[col]-float(r[col])))
                        assert np.isclose(m[col],float(r[col]),rtol=1e-11,atol=2e-14)
                    if m['relative']>worst['relative']: worst=dict(**m,key=key,quantity=quantity,direction=direction,row=row)
        oracle_pair={k:measure(oracle[f'p{p}_{k}80'],oracle[f'p{p}_{k}']) for k in ('B','D','H')}
        dot_l=np.vdot(a[f'p{p}_forward'][:,0],g);dot_r=np.vdot(c[0],a[f'p{p}_adjoint'])
        dot=measure(dot_l,dot_r)
        per_degree[str(p)]=dict(full_columns=dim,case_count=24,direction_count=3,worst=worst,whole=whole,own_action_identity=own_identity,oracle80_110=oracle_pair,adjoint_dot=dot,H_min=float(H.min()),H_max=float(H.max()),near_zero_csv_rows=nears)
    cost=read(pathlib.Path(idx['run_directory'])/'run_summary.json')
    declared=records['local_cold_comparison_v23.json']['implementations'][name]
    for k,key in [('full_launch_seconds','launch_to_summary_seconds_monotonic'),('simultaneous_tree_peak_bytes','sampled_process_tree_rss_peak_bytes')]: assert declared[k]==cost[key]
    assert cost['classification']=='COMPLETED' and cost['descendants_cleared'] and cost['sampled_process_tree_swap_peak_bytes']==0
    implementations[name]=dict(source=idx['source_sha'],interval_max_absolute=float(interval.max()),worst_interval=dict(index=int(wi[0]),degree=int(wi[1]),omega=float(oracle['frequencies'][wi[0]])),per_degree=per_degree,full_seconds=cost['launch_to_summary_seconds_monotonic'],worker_seconds=idx['result']['worker_cold_seconds'],peak_bytes=cost['sampled_process_tree_rss_peak_bytes'])
    assert interval.max() <= 1e-12
    assert all(v['worst']['relative']<=1e-10 and all(x['relative']<=1e-10 for x in v['whole'].values()) for v in per_degree.values())
test=records['targeted_tests_v23.json'];junit=test['final_XML'];jp=pathlib.Path(junit['path'])
assert digest(jp)==junit['sha256']
suites=list(ET.parse(jp).getroot().iter('testsuite'))
totals={k:sum(int(x.attrib.get(k,0)) for x in suites) for k in ('tests','failures','errors','skipped')}
assert totals==dict(tests=47,failures=0,errors=0,skipped=0)
tested_blobs=[]
for item in test['tested_files']:
    p=str(pathlib.Path(item['path']).relative_to(ROOT))
    b=subprocess.check_output(['git','show','7a7c6b5a3a0c65a93e362644b50ad84ae0d20f2c:'+p])
    assert hashlib.sha256(b).hexdigest()==item['sha256']==digest(item['path'])
    tested_blobs.append(p)
strict={}
for role,v in records['strict_admission_v23.json'].items():
    metrics=v['evidence']['metrics']; thresholds={'stored_operator_arithmetic':1e-10,'oracle_self_consistency':1e-10,'actual_vector_projection':1e-10,'original_equation':1e-6,'MPC':1e-10,'affine':1e-10}
    failed=[k for k,t in thresholds.items() if type(metrics.get(k)) not in (float,int) or not np.isfinite(metrics[k]) or not 0<=metrics[k]<=t]
    assert set(failed).issubset(set(v['derived']['failed']))
    assert not v['derived']['strict_complete_qualified'] and not v['derived']['solve_admitted']
    strict[role]=dict(metrics=metrics,independently_failed=failed,entry_rejections=v['entry_rejections'])
a,b=implementations['analytic'],implementations['q60']
costs=dict(time_gain=1-a['full_seconds']/b['full_seconds'],rss_gain=1-a['peak_bytes']/b['peak_bytes'],worker_ratio=a['worker_seconds']/b['worker_seconds'],mandatory60s_fraction={k:60/v['full_seconds'] for k,v in implementations.items()},no_retiming=True)
assert costs['time_gain']<.2 and costs['rss_gain']<.2
data=dict(bindings=checks,compact_records_read=list(records),indices_read=list(index),raw_shapes={k:dict(shape=list(v.shape),dtype=str(v.dtype)) for k,v in oracle.items()},moment80_110_max=mom_self,decimal_strings_round_to_saved_array=True,implementations=implementations,csv_rows=compared,csv_max_absolute_recomputation_difference=csv_abs,strict_roles=strict,tests=totals,tested_blobs_match_source=tested_blobs,costs=costs,operations=dict(new_native_basis=0,new_quadrature=0,FE_action=0,factor=0,solve=0,NN=0,saved_local_array_products=True),elapsed_seconds=time.monotonic()-start)
(OUT/'saved_audit.json').write_text(json.dumps(data,indent=2)+'\n')
print(json.dumps({k:data[k] for k in ('csv_rows','moment80_110_max','csv_max_absolute_recomputation_difference','tests','costs','elapsed_seconds')},indent=2))
print('bindings',len(checks),'unresolved',[(x['path'],x['expected'],x['actual']) for x in checks if x['status']!='PASS'])
print('worst', {name:{p:v['worst'] for p,v in imp['per_degree'].items()} for name,imp in implementations.items()})
